package watch

import (
	"bytes"
	"encoding/json"
	"fmt"
	"io"
	"os"
	"path/filepath"
	"strings"
)

// OpenCode has no hook config to merge: a plugin file in its plugins
// folder is loaded on start. Rex writes one small generated file there,
// and it only ever pipes events to `rex ingest --source opencode`.

const opencodeMarker = "// generated by rex — safe to delete"

// openCodeTypes are the payload types the plugin sends.
var openCodeTypes = map[string]bool{
	"chat.message": true, "message.part.updated": true, "session.idle": true, "session.error": true,
	"permission.updated": true, "permission.asked": true, "question.asked": true,
}

// opencodePluginJS is the plugin. It never throws from a hook, never waits
// for rex, never sets output, and sends no file bodies: write content,
// edit strings and patch text are dropped before anything leaves.
const opencodePluginJS = opencodeMarker + `
// Pipes OpenCode events to rex, which only watches: https://github.com/luciancheng/rex
import { spawn } from "node:child_process"
const REX = %s
let q = Promise.resolve()
function send(p) {
  let line
  try { line = JSON.stringify(p) + "\n" } catch { return }
  q = q.then(() => new Promise((done) => {
    try {
      const c = spawn(REX, ["ingest", "--source", "opencode"], { stdio: ["pipe", "ignore", "ignore"], windowsHide: true })
      const t = setTimeout(() => { try { c.kill() } catch {} ; done() }, 5000)
      c.on("error", () => { clearTimeout(t); done() })
      c.on("close", () => { clearTimeout(t); done() })
      c.stdin.on("error", () => {})
      c.stdin.end(line)
    } catch { done() }
  })).catch(() => {})
}
const slim = (s = {}) => {
  const { output, metadata, raw, ...rest } = s
  const input = { ...(s.input || {}) }
  delete input.content; delete input.oldString; delete input.newString; delete input.patchText
  const files = Array.isArray(metadata?.files) ? metadata.files.map((f) => f?.filePath).filter(Boolean) : undefined
  return { ...rest, input, files }
}
export const RexPlugin = async (ctx) => {
  const cwd = ctx?.directory || ctx?.worktree || ""
  const roles = new Map(), seen = new Set()
  return {
    event: async ({ event }) => {
      try {
        const p = event?.properties ?? {}
        switch (event?.type) {
          case "message.updated":
            if (p.info?.id) roles.set(p.info.id, p.info.role)
            return
          case "message.part.updated": {
            const part = p.part
            if (!part) return
            if (part.type === "tool") {
              const st = part.state?.status, key = part.callID + ":" + st
              if (["running", "completed", "error"].includes(st) && !seen.has(key)) {
                seen.add(key)
                send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: "tool", tool: part.tool, callID: part.callID, state: slim(part.state) } })
              }
              return
            }
            if ((part.type === "text" || part.type === "reasoning") && part.time?.end && !part.synthetic && !part.ignored && roles.get(part.messageID) === "assistant")
              send({ type: event.type, cwd, sessionID: part.sessionID, part: { type: part.type, text: part.text } })
            return
          }
          case "session.idle": case "session.error": case "permission.updated": case "permission.asked": case "question.asked":
            send({ type: event.type, cwd, properties: p })
            return
        }
      } catch {}
    },
    "chat.message": async (input, output) => {
      try {
        const text = (output?.parts ?? []).filter((x) => x?.type === "text" && !x.synthetic && !x.ignored).map((x) => x.text).join("\n").trim()
        if (text) send({ type: "chat.message", cwd, sessionID: input?.sessionID, text })
      } catch {}
    },
  }
}
`

// opencodeDir is OpenCode's config folder: $XDG_CONFIG_HOME/opencode, else
// ~/.config/opencode (on every OS).
func opencodeDir(home string) string {
	if x := os.Getenv("XDG_CONFIG_HOME"); x != "" {
		return filepath.Join(x, "opencode")
	}
	return filepath.Join(home, ".config", "opencode")
}

func opencodePlugin(home string) string { return filepath.Join(opencodeDir(home), "plugins", "rex.js") }

func opencodeSource(exe string) []byte {
	q, _ := json.Marshal(exe)
	return []byte(fmt.Sprintf(opencodePluginJS, q))
}

// installOpenCode writes the plugin atomically. A rex.js that Rex didn't
// write is left alone.
func installOpenCode(path string, out io.Writer) error {
	want := opencodeSource(rexExecutable())
	if have, err := os.ReadFile(path); err == nil {
		if !bytes.HasPrefix(have, []byte(opencodeMarker)) {
			return fmt.Errorf("%s exists and Rex didn't write it; move it to install the rex plugin", path)
		}
		if bytes.Equal(have, want) {
			fmt.Fprintf(out, "opencode plugin already installed at %s\n", path)
			return nil
		}
	}
	if err := writeFileAtomic(path, want, 0o644); err != nil {
		return err
	}
	fmt.Fprintf(out, "installed opencode plugin at %s (restart OpenCode to load it)\n", path)
	fmt.Fprintf(out, "feed: %s\n", DefaultEventPath())
	return nil
}

func uninstallOpenCode(path string, out io.Writer) error {
	have, err := os.ReadFile(path)
	if os.IsNotExist(err) {
		fmt.Fprintf(out, "opencode: no rex plugin at %s\n", path)
		return nil
	}
	if err != nil {
		return err
	}
	if !bytes.HasPrefix(have, []byte(opencodeMarker)) {
		return fmt.Errorf("%s wasn't written by Rex; leaving it", path)
	}
	if err := os.Remove(path); err != nil {
		return err
	}
	fmt.Fprintf(out, "removed the rex plugin from %s\n", path)
	return nil
}

// writeFileAtomic writes data to path through a temp file in the same
// folder, so OpenCode never loads half a plugin.
func writeFileAtomic(path string, data []byte, mode os.FileMode) error {
	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o755); err != nil {
		return err
	}
	tmp, err := os.CreateTemp(dir, "."+filepath.Base(path)+".rex-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name())
	if _, err := tmp.Write(data); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	if err := os.Chmod(tmp.Name(), mode); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

// MapOpenCode maps one payload from the rex plugin.
func MapOpenCode(payload map[string]any) *Event {
	cwd := strField(payload, "cwd")
	event := func(kind, text string, meta map[string]any) *Event {
		if strings.TrimSpace(text) == "" {
			return nil
		}
		ev := NewEvent("opencode", kind, text, meta)
		return &ev
	}
	abs := func(p string) string {
		if p != "" && !filepath.IsAbs(p) && cwd != "" {
			return filepath.Join(cwd, p)
		}
		return p
	}
	switch strField(payload, "type") {
	case "chat.message":
		return event("user", strings.TrimSpace(strField(payload, "text")), nil)
	case "message.part.updated":
		part := asDict(payload["part"])
		switch strField(part, "type") {
		case "text":
			return event("text", strings.TrimSpace(strField(part, "text")), nil)
		case "reasoning":
			return event("thought", strings.TrimSpace(strField(part, "text")), nil)
		case "tool":
			return openCodeTool(part, abs, event)
		}
	case "session.idle":
		return event("idle", "turn completed", nil)
	case "session.error":
		props := asDict(payload["properties"])
		msg := strField(asDict(props["error"]), "message")
		if msg == "" {
			msg = strField(props, "error")
		}
		return event("error", strings.TrimSpace("session error: "+msg), nil)
	case "permission.updated", "permission.asked":
		props := asDict(payload["properties"])
		text := strField(props, "title")
		if text == "" {
			text = strings.TrimSpace(strField(props, "permission") + " " + strField(props, "type"))
		}
		return event("question", "permission: "+text, nil)
	case "question.asked":
		props := asDict(payload["properties"])
		return event("question", toolText("question", props), toolMeta("question", ""))
	}
	return nil
}

func openCodeTool(part map[string]any, abs func(string) string, event func(string, string, map[string]any) *Event) *Event {
	tool := strField(part, "tool")
	state := asDict(part["state"])
	input := asDict(state["input"])
	status := strField(state, "status")
	var paths []any
	if p := abs(strField(input, "filePath")); p != "" {
		paths = append(paths, p)
	}
	if files, ok := state["files"].([]any); ok {
		for _, f := range files {
			if s, ok := f.(string); ok && s != "" {
				paths = append(paths, abs(s))
			}
		}
	}
	first := ""
	if len(paths) > 0 {
		first = paths[0].(string)
	}
	meta := toolMeta(tool, first)
	if len(paths) > 1 {
		meta["paths"] = paths
	}
	cmd := strings.TrimSpace(asCommand(input["command"]))
	edit := IsFileEditTool(tool) || tool == "apply_patch"
	switch status {
	case "running":
		switch {
		case IsShellTool(tool):
			meta["command"] = cmd
			return event("command", cmd, meta)
		case first != "":
			return event(toolKind(tool), tool+" "+first, meta)
		}
		return event(toolKind(tool), toolText(tool, state["input"]), meta)
	case "completed":
		switch {
		case edit && first != "":
			meta["ok"] = true
			return event("result", "wrote "+first, meta)
		case IsShellTool(tool):
			meta["command"] = cmd
			return event("result", "ran "+cmd, meta)
		}
		return event("result", tool, meta)
	case "error":
		meta["ok"] = false
		text := tool + " failed"
		if IsShellTool(tool) && cmd != "" {
			meta["command"] = cmd
			text += " · " + cmd
		} else if first != "" {
			text += " · " + first
		}
		if e := strings.TrimSpace(strField(state, "error")); e != "" {
			text += ": " + firstLine(e)
		}
		return event("error", text, meta)
	}
	return nil
}

func init() {
	registerHarness(Harness{
		Name:    "opencode",
		Label:   "OpenCode",
		Config:  opencodePlugin,
		Present: func(home string) bool { return dirExists(opencodeDir(home)) },
		Wired: func(home string) bool {
			data, err := os.ReadFile(opencodePlugin(home))
			return err == nil && bytes.HasPrefix(data, []byte(opencodeMarker))
		},
		Install: func(home string, out io.Writer) error {
			if !dirExists(opencodeDir(home)) {
				fmt.Fprintf(out, "opencode: OpenCode isn't set up here (no %s); nothing changed\n", opencodeDir(home))
				return nil
			}
			return installOpenCode(opencodePlugin(home), out)
		},
		Uninstall: func(home string, out io.Writer) error { return uninstallOpenCode(opencodePlugin(home), out) },
	})
}
